<?php
declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';
use App\Security\Csrf;use App\Services\Auth;use App\Services\NotificationService;use App\Support\Url;
Auth::requirePermission('NOTIFICATION_VIEW_OWN');$uid=(int)Auth::user()['id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid token.');$action=(string)($_POST['action']??'');
 if($action==='read')NotificationService::read((int)$_POST['id'],$uid);
 elseif($action==='close')NotificationService::close((int)$_POST['id'],$uid);
 elseif($action==='open'){$target=NotificationService::openTarget((int)$_POST['id'],$uid);header('Location: '.($target?Url::to($target):Url::to('notifications/index.php?updated=1')));exit;}
 elseif($action==='send')NotificationService::sendManaged((string)($_POST['target_type']??''),(string)($_POST['target']??''),(string)($_POST['title']??''),(string)($_POST['message']??''),(string)($_POST['priority']??'normal'),$uid);
 else throw new RuntimeException('Invalid action.');
 $scroll=max(0,min(1000000,(int)($_POST['scroll_y']??0)));header('Location: ?updated=1&scroll='.$scroll);exit;
}catch(RuntimeException$e){$errors[]=$e->getMessage();}
$rows=NotificationService::inbox($uid);$pageTitle='Notifications';require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><span class="eyebrow dark">Communication centre</span><h1>Notifications</h1><p>Operational, shipment, payment and system updates—delivered only to the intended account or chosen audience.</p></div><span class="badge"><?=h(NotificationService::unread($uid))?> unread</span></div>
<?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<?php if(Auth::can('NOTIFICATION_MANAGE')):?><form method="post" class="card feature-card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="send"><h2>Send a notification</h2><p class="muted">Individual delivery is the default. Choose a role or all accounts only when a genuine broadcast is required.</p><div class="form-grid"><div class="field"><label>Delivery type</label><select name="target_type" class="notification-target-type"><option value="individual" selected>One account by email</option><option value="role">A specific role</option><option value="all">All active accounts</option></select></div><div class="field notification-target individual"><label>Recipient email</label><input type="email" name="target" placeholder="name@company.com"></div><div class="field notification-target role" hidden><label>Role audience</label><select data-name="target"><option value="MCCOLLIN_OPERATIONS">Operations</option><option value="MCCOLLIN_FINANCE">Finance</option><option value="SHIPPER">Shippers</option><option value="TRUCK_OWNER">Carriers</option><option value="DRIVER">Drivers</option></select></div><div class="field"><label>Priority</label><select name="priority"><option>normal</option><option>high</option><option>critical</option></select></div><div class="field"><label>Title</label><input name="title" maxlength="191" required></div><div class="field full"><label>Message</label><textarea name="message" maxlength="1000" required></textarea></div></div><button class="button">Send securely</button></form><?php endif;?>
<div class="notification-list"><?php foreach($rows as$n):?><article class="card notification-card <?=$n['read_at']?'':'unread'?>" id="notification-<?=h($n['notification_id'])?>"><div class="notification-main"><div><div class="notification-meta"><span class="status-pill"><?=h($n['priority'])?></span><strong><?=h(str_replace('_',' ',$n['category']))?></strong><time><?=h($n['emitted_at'])?></time></div><h3><?=h($n['title'])?></h3><p><?=h($n['message'])?></p></div><?php if(!$n['read_at']):?><span class="unread-dot" title="Unread"></span><?php endif;?></div><div class="notification-actions"><?php if($n['action_url']):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="open"><input type="hidden" name="id" value="<?=h($n['notification_id'])?>"><button class="button">Open</button></form><?php endif;?><?php if(!$n['read_at']):?><form method="post" class="notification-action"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=h($n['notification_id'])?>"><input type="hidden" name="scroll_y" value="0"><button class="button secondary">Mark as read</button></form><?php endif;?><form method="post" class="notification-action"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="close"><input type="hidden" name="id" value="<?=h($n['notification_id'])?>"><input type="hidden" name="scroll_y" value="0"><button class="button quiet">Close</button></form></div></article><?php endforeach;?><?php if(!$rows):?><div class="card empty-state"><h3>All clear</h3><p>No active notifications.</p></div><?php endif;?></div>
<?php require BASE_PATH.'/app/Views/layout/footer.php';?>
